export interface DesignExportSlice {id:string;label:string;selected:boolean;formatId:string;scale:number;transparent:boolean;trimTransparentBounds:boolean;suffix:string;unavailableReason?:string}
export interface MultiExportSlicesProps extends Omit<ViewProps,'children'>,ScopedControlProps {slices:readonly DesignExportSlice[];selectedId:string|null;formats:readonly {id:string;label:string;alpha:boolean}[];presets:readonly {id:string;label:string}[];presetId:string;status:'idle'|'running'|'complete'|'error';progress:number;results:readonly {id:string;sliceId:string;label:string;bytes:number}[];renderPreview:(id:string)=>ReactNode;onSelect:(id:string)=>void;onCommit:(slice:DesignExportSlice,signal?:AbortSignal)=>unknown;onPreset:(id:string,signal?:AbortSignal)=>unknown;onExport:(slices:readonly DesignExportSlice[],signal?:AbortSignal)=>unknown;onCancel:()=>unknown;onRevealResult:(id:string)=>void;unstyled?:boolean}
export function MultiExportSlices({scope='export-slices',revision=0,...props}:MultiExportSlicesProps){const {slices,selectedId,formats,presets,presetId,status,progress,results,renderPreview,onSelect:_select,onCommit:_commit,onPreset:_preset,onExport:_export,onCancel,onRevealResult:_reveal,unstyled=false,disabledReason,style,...rest}=props;
 if(slices.length>4096||formats.length>64||presets.length>512||new Set(slices.map(s=>s.id)).size!==slices.length||slices.some(s=>!s.id.trim()||!Number.isFinite(s.scale)||s.scale<.01||s.scale>32||s.suffix.length>256)||!Number.isFinite(progress)||progress<0||progress>1||results.length>16384||results.some(r=>!Number.isSafeInteger(r.bytes)||r.bytes<0))throw new RangeError('Invalid export slice job');
 const owner=JSON.stringify([...controlIdentity(scope,revision),disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined||status==='running'),off=guard.pending||disabledReason!==undefined||status==='running',selected=slices.find(s=>s.id===selectedId);
 return <View {...rest} style={[{gap:space[2]},style]}><PropertyInspector scope={scope} revision={revision} label="Export preset" disabledReason={off?'Export configuration unavailable':undefined} unstyled={unstyled} fields={[{kind:'choice',id:'preset',label:'Preset',value:presetId,choices:presets}]} onCommit={(_id,value)=>guard.run('preset',(h,s)=>h.presets.some(p=>p.id===value)?h.onPreset(String(value),s):undefined)}/><FlatList style={{height:240}} data={slices} keyExtractor={s=>s.id} renderItem={({item})=><View>{renderPreview(item.id)}<Button title={item.label+(item.selected?' · included':' · excluded')} variant="secondary" accessibilityState={{selected:item.id===selectedId}} disabled={off} unstyled={unstyled} onPress={()=>{const h=guard.current();if(h?.slices.some(s=>s.id===item.id))h.onSelect(item.id);}}/></View>}/>
 {selected?<PropertyInspector scope={scope} revision={revision} label="Export slice settings" disabledReason={off?'Export configuration unavailable':selected.unavailableReason} unstyled={unstyled} fields={[{kind:'boolean',id:'selected',label:'Include slice',value:selected.selected},{kind:'choice',id:'formatId',label:'Format',value:selected.formatId,choices:formats},{kind:'number',id:'scale',label:'Resolution multiplier',value:selected.scale,min:.01,max:32,step:.25},{kind:'boolean',id:'transparent',label:'Transparent output',value:selected.transparent,disabledReason:formats.find(f=>f.id===selected.formatId)?.alpha?undefined:'Format has no alpha channel'},{kind:'boolean',id:'trimTransparentBounds',label:'Trim transparent bounds',value:selected.trimTransparentBounds},{kind:'text',id:'suffix',label:'File suffix',value:selected.suffix,maxLength:256}]} onCommit={(id,value)=>guard.run('slice',(h,s)=>{const slice=h.slices.find(s=>s.id===h.selectedId);if(!slice||slice.unavailableReason!==undefined)return;const next={...slice,[id]:value};if(!h.formats.some(f=>f.id===next.formatId))throw new Error('Export format unavailable');if(!h.formats.find(f=>f.id===next.formatId)?.alpha)next.transparent=false;return h.onCommit(next,s);})}/>:null}
 <Button title="Export selected slices" disabled={off||!slices.some(s=>s.selected)} unstyled={unstyled} onPress={()=>guard.run('export',(h,s)=>{const selected=h.slices.filter(s=>s.selected);if(!selected.length||selected.some(s=>s.unavailableReason!==undefined||!h.formats.some(f=>f.id===s.formatId&&(!s.transparent||f.alpha))))throw new Error('One or more slices cannot be exported');return h.onExport(selected,s);})}/>{status==='running'||guard.pending?<Button title="Cancel slice export" variant="secondary" unstyled={unstyled} onPress={()=>{if(guard.cancel())return onCancel();}}/>:null}<Text accessibilityLiveRegion="polite" {...{className:unstyled?undefined:'text-text'}}>{status==='running'?'Exporting '+Math.round(progress*100)+'%':status==='complete'?'Host acknowledged '+results.length+' output assets':status}</Text><FlatList style={{height:160}} data={results} keyExtractor={r=>r.id} renderItem={({item})=><Button title={item.label+' · '+item.bytes+' bytes'} unstyled={unstyled} onPress={()=>{const h=guard.current();if(h?.results.some(r=>r.id===item.id))h.onRevealResult(item.id);}}/>}/><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View>;}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

